+
+#[derive(Clone, Copy, Debug, Eq, PartialEq)]
+struct PanePoint {
+    row: usize,
+    column: usize,
+}
+
+impl PanePoint {
+    fn clamped(self, width: usize, height: usize) -> Self {
+        if width == 0 || height == 0 {
+            return Self { row: 0, column: 0 };
+        }
+        Self {
+            row: self.row.min(height - 1),
+            column: self.column.min(width - 1),
+        }
+    }
+}
