+    fn clear_visual_selection(&mut self) {
+        self.visual_selection = None;
+    }
+
+    fn start_visual_selection(&mut self, kind: VisualSelectionKind) {
+        let focus = if self.left_visible {
+            self.focus
+        } else {
+            PaneFocus::Right
+        };
+        let anchor = self.current_pane_point(focus);
+        self.visual_selection = Some(VisualSelection {
+            focus,
+            kind,
+            anchor,
+            cursor: anchor,
+        });
+        self.pending = None;
+        self.mode = UiMode::Command;
+    }
+
+    fn handle_visual_key(&mut self, key: UiKey) -> Vec<UiAction> {
+        match key {
+            UiKey::Esc => self.clear_visual_selection(),
+            UiKey::Char('v') => self.set_or_toggle_visual_kind(VisualSelectionKind::Character),
+            UiKey::Char('V') => self.set_or_toggle_visual_kind(VisualSelectionKind::Line),
+            UiKey::Char(CTRL_V_CHAR) => self.set_or_toggle_visual_kind(VisualSelectionKind::Block),
+            UiKey::Char('y') => self.yank_visual_selection(false),
+            UiKey::Char('Y') => self.yank_visual_selection(true),
+            UiKey::Char('h') | UiKey::Left => self.move_visual_cursor(0, -1),
+            UiKey::Char('j') | UiKey::Down => self.move_visual_cursor(1, 0),
+            UiKey::Char('k') | UiKey::Up => self.move_visual_cursor(-1, 0),
+            UiKey::Char('l') | UiKey::Right => self.move_visual_cursor(0, 1),
+            _ => {}
+        }
+        Vec::new()
+    }
+
+    fn set_or_toggle_visual_kind(&mut self, kind: VisualSelectionKind) {
+        let Some(selection) = self.visual_selection.as_mut() else {
+            return;
+        };
+        if selection.kind == kind {
+            self.clear_visual_selection();
+        } else {
+            selection.kind = kind;
+        }
+    }
+
+    fn move_visual_cursor(&mut self, row_delta: isize, column_delta: isize) {
+        let Some(focus) = self.visual_selection.as_ref().map(|selection| selection.focus) else {
+            return;
+        };
+        let (width, height) = self.pane_inner_size(focus);
+        let Some(selection) = self.visual_selection.as_mut() else {
+            return;
+        };
+        if width == 0 || height == 0 {
+            return;
+        }
+        selection.cursor = PanePoint {
+            row: offset_coordinate(selection.cursor.row, row_delta, height),
+            column: offset_coordinate(selection.cursor.column, column_delta, width),
+        };
+    }
+
+    fn yank_visual_selection(&mut self, force_line: bool) {
+        let Some(selection) = self.visual_selection.clone() else {
+            return;
+        };
+        let text = self.visual_selection_text(&selection, force_line);
+        self.store_yank(text);
+        self.clear_visual_selection();
+    }
+
+    fn yank_current_line(&mut self) {
+        let focus = if self.left_visible {
+            self.focus
+        } else {
+            PaneFocus::Right
+        };
+        let point = self.current_pane_point(focus);
+        let text = self
+            .pane_lines(focus)
+            .get(point.row)
+            .cloned()
+            .unwrap_or_default();
+        self.store_yank(text);
+    }
+
+    fn store_yank(&mut self, text: String) {
+        let copied_chars = text.chars().count();
+        self.yank_register = Some(text);
+        self.show_status_notice(
+            format!("copied {copied_chars} chars"),
+            Duration::from_secs(STATUS_NOTICE_SECONDS),
+        );
+    }
+
+    fn visual_selection_text(&self, selection: &VisualSelection, force_line: bool) -> String {
+        let (width, height) = self.pane_inner_size(selection.focus);
+        if width == 0 || height == 0 {
+            return String::new();
+        }
+        let lines = self.pane_lines(selection.focus);
+        let row_start = selection.anchor.row.min(selection.cursor.row).min(height - 1);
+        let row_end = selection.anchor.row.max(selection.cursor.row).min(height - 1);
+        let mut selected = Vec::new();
+        for row in row_start..=row_end {
+            let line = lines.get(row).map(String::as_str).unwrap_or("");
+            let Some((column_start, column_end)) =
+                selected_columns_for_row(selection, row, width, force_line)
+            else {
+                continue;
+            };
+            if force_line || selection.kind == VisualSelectionKind::Line {
+                selected.push(line.to_string());
+            } else {
+                selected.push(slice_line_columns(line, column_start, column_end));
+            }
+        }
+        selected.join("\n")
+    }
+
+    fn pane_lines(&self, focus: PaneFocus) -> Vec<String> {
+        match focus {
+            PaneFocus::Left if self.left_visible => {
+                let (width, _) = self.pane_inner_size(PaneFocus::Left);
+                self.left_display_rows(width)
+                    .into_iter()
+                    .map(|row| row.text)
+                    .collect()
+            }
+            PaneFocus::Left => Vec::new(),
+            PaneFocus::Right => self
+                .visible_right_content(&self.last_right_content)
+                .lines()
+                .map(str::to_string)
+                .collect(),
+        }
+    }
+
+    fn current_pane_point(&self, focus: PaneFocus) -> PanePoint {
+        let (width, height) = self.pane_inner_size(focus);
+        let point = match focus {
+            PaneFocus::Left => PanePoint {
+                row: self.control_selected,
+                column: 0,
+            },
+            PaneFocus::Right => self.right_cursor_pane_point(),
+        };
+        point.clamped(width, height)
+    }
+
+    fn right_cursor_pane_point(&self) -> PanePoint {
+        let visible_right_content = self.visible_right_content(&self.last_right_content);
+        let (row, column) = self.right_cursor_position_with_cursor(&visible_right_content, None);
+        let layout = self.layout();
+        PanePoint {
+            row: usize::from(row.saturating_sub(2)),
+            column: usize::from(column.saturating_sub(layout.left_width.saturating_add(2))),
+        }
+    }
+
+    fn pane_inner_size(&self, focus: PaneFocus) -> (usize, usize) {
+        match focus {
+            PaneFocus::Left if self.left_visible => {
+                let (width, height) = self.left_inner_size();
+                (usize::from(width), usize::from(height))
+            }
+            PaneFocus::Left => (0, 0),
+            PaneFocus::Right => {
+                let (width, height) = self.right_inner_size();
+                (usize::from(width), usize::from(height))
+            }
+        }
+    }
+
+    fn pane_inner_origin(&self, focus: PaneFocus) -> (u16, u16) {
+        match focus {
+            PaneFocus::Left => (1, 1),
+            PaneFocus::Right => (self.layout().left_width.saturating_add(1), 1),
+        }
+    }
+
+    fn apply_visual_selection(&self, buffer: &mut Buffer) {
+        let Some(selection) = self.visual_selection.as_ref() else {
+            return;
+        };
+        let (width, height) = self.pane_inner_size(selection.focus);
+        if width == 0 || height == 0 {
+            return;
+        }
+        let row_start = selection.anchor.row.min(selection.cursor.row).min(height - 1);
+        let row_end = selection.anchor.row.max(selection.cursor.row).min(height - 1);
+        let (origin_x, origin_y) = self.pane_inner_origin(selection.focus);
+        for row in row_start..=row_end {
+            let Some((column_start, column_end)) =
+                selected_columns_for_row(selection, row, width, false)
+            else {
+                continue;
+            };
+            for column in column_start..=column_end {
+                let x = origin_x.saturating_add(column.min(width - 1) as u16);
+                let y = origin_y.saturating_add(row.min(height - 1) as u16);
+                if x < buffer.area.width && y < buffer.area.height {
+                    buffer.get_mut(x, y).modifier.insert(Modifier::REVERSED);
+                }
+            }
+        }
+    }

